\usepackage{amssymb}
\usepackage{multirow}

\title{What Makes Multi-Turn Jailbreaks Detectable? Domain Exposure Bridges the Cross-Attack Gap}

\author{Anonymous}

\begin{document}
\maketitle

\input{abstract}

\input{introduction}

